import { run } from "@grammyjs/runner";
import { existsSync, mkdirSync, readFileSync, unlinkSync, writeFileSync } from "fs";
import type { Bot, Context } from "grammy";
import { ALLOWED_USERS, RESTART_FILE, SYS_MSG_PREFIX, WORKING_DIR } from "../config";

const RESTART_MARKER_FILE = "/tmp/soma-restart-marker.json";
const CRASH_MARKER_FILE = "/tmp/soma-crash-marker.json";
import { createProviderOrchestrator } from "../providers/create-orchestrator";
import type { ProviderRetryPolicyMap } from "../providers/retry-policy";
import { addSystemReaction, sendSystemMessage } from "../utils/system-message";
import { PendingFormStore } from "../stores/pending-form-store";
import { sessionManager } from "../core/session/session-manager";
import { setBotUsername } from "../handlers";
import {
  createTelegramBot,
  registerBotCommands,
  registerBotHandlers,
  registerBotMiddleware,
} from "./telegram-bot";
import { configureAndStartScheduler, stopSchedulerRunner } from "./scheduler-runner";

interface SessionStatsSnapshot {
  totalSessions: number;
  totalQueries: number;
  totalInputTokens: number;
  totalOutputTokens: number;
  sessions: Array<{
    sessionKey: string;
    queries: number;
    isActive: boolean;
    isRunning: boolean;
  }>;
}

interface SessionPort {
  isActive: boolean;
  sessionStartTime: Date | null;
  currentContextTokens: number;
  contextWindowSize: number;
  actualContextMax: number | null;
  totalQueries: number;
  totalInputTokens: number;
  totalOutputTokens: number;
  hasSteeringMessages(): boolean;
  getSteeringCount(): number;
  consumeSteering(): string | null;
  formatToolStats(): string;
  nextQueryContext: { userId: number; context: string } | null;
  sendMessageStreaming(
    prompt: string,
    statusCallback: (
      statusType: string,
      content: string,
      segmentId?: number,
      metadata?: unknown
    ) => Promise<void>,
    chatId?: number,
    modelContext?: string
  ): Promise<string>;
}

interface SessionManagerPort {
  getGlobalStats(): SessionStatsSnapshot;
  getSession(userId: number): SessionPort;
  getSessionByKey(sessionKey: string): SessionPort;
  saveAllSessions(): void;
  setProviderOrchestrator?(
    orchestrator: ReturnType<typeof createProviderOrchestrator>
  ): void;
}

interface FormStorePort {
  loadForms(): Promise<number>;
}

interface RunnerPort {
  isRunning(): boolean;
  stop(): void;
}

interface FileOps {
  existsSync(path: string): boolean;
  readFileSync(path: string, encoding: BufferEncoding): string;
  unlinkSync(path: string): void;
  writeFileSync(path: string, content: string, encoding?: BufferEncoding): void;
  mkdirSync(path: string, options?: { recursive?: boolean }): void;
}

export interface VerificationTask {
  command: string;
  bdTaskId: string;
  description: string;
}

export interface BootstrappedApplication {
  bot: Bot<Context>;
  runner: RunnerPort;
  formStore: FormStorePort;
  stopRunner: () => void;
  handleSigterm: () => Promise<void>;
  setVerificationTask: (task: VerificationTask | null) => void;
  /** Best-effort crash notification to user before process dies */
  notifyCrash?: (reason: string, error?: unknown) => void;
}

interface BootstrapDependencies {
  createTelegramBot?: () => Bot<Context>;
  registerBotMiddleware?: (bot: Bot<Context>) => void;
  registerBotCommands?: (bot: Bot<Context>) => Promise<void>;
  registerBotHandlers?: (bot: Bot<Context>) => void;
  configureAndStartScheduler?: (
    botApi: Bot<Context>["api"],
    manager: SessionManagerPort
  ) => void;
  stopSchedulerRunner?: () => void;
  startRunner?: (bot: Bot<Context>) => RunnerPort;
  sessionManager?: SessionManagerPort;
  createFormStore?: () => FormStorePort;
  fs?: FileOps;
  sendSystemMessage?: typeof sendSystemMessage;
  addSystemReaction?: typeof addSystemReaction;
  sleep?: (ms: number) => Promise<void>;
  createProviderOrchestrator?: typeof createProviderOrchestrator;
  execSync?: (command: string) => { status: number; stdout: string; stderr: string };
}

const defaultFileOps: FileOps = {
  existsSync,
  readFileSync,
  unlinkSync,
  writeFileSync,
  mkdirSync,
};

function parseProviderRetryPoliciesFromEnv(
  raw: string | undefined
): Partial<ProviderRetryPolicyMap> | undefined {
  if (!raw) {
    return undefined;
  }

  try {
    const parsed = JSON.parse(raw) as Record<
      string,
      { maxRetries?: unknown; baseBackoffMs?: unknown }
    >;
    const entries = Object.entries(parsed).filter(([, policy]) => {
      return (
        typeof policy.maxRetries === "number" &&
        typeof policy.baseBackoffMs === "number"
      );
    });
    if (entries.length === 0) {
      return undefined;
    }
    return Object.fromEntries(entries) as Partial<ProviderRetryPolicyMap>;
  } catch (error) {
    console.warn(
      "[Provider] Failed to parse PROVIDER_RETRY_POLICIES_JSON, using defaults:",
      error
    );
    return undefined;
  }
}

export async function bootstrapApplication(
  dependencies: BootstrapDependencies = {}
): Promise<BootstrappedApplication> {
  const createBot = dependencies.createTelegramBot ?? createTelegramBot;
  const registerMiddleware =
    dependencies.registerBotMiddleware ?? registerBotMiddleware;
  const registerCommands = dependencies.registerBotCommands ?? registerBotCommands;
  const registerHandlers = dependencies.registerBotHandlers ?? registerBotHandlers;
  const configureScheduler =
    dependencies.configureAndStartScheduler ??
    ((botApi: Bot<Context>["api"], managerPort: SessionManagerPort) =>
      configureAndStartScheduler(
        botApi,
        managerPort as Parameters<typeof configureAndStartScheduler>[1]
      ));
  const stopScheduler = dependencies.stopSchedulerRunner ?? stopSchedulerRunner;
  const startRunner =
    dependencies.startRunner ??
    ((bot: Bot<Context>): RunnerPort => run(bot) as unknown as RunnerPort);
  const manager = dependencies.sessionManager ?? (sessionManager as SessionManagerPort);
  const createFormStore =
    dependencies.createFormStore ?? (() => new PendingFormStore());
  const fsOps = dependencies.fs ?? defaultFileOps;
  const sendSystemMessageFn = dependencies.sendSystemMessage ?? sendSystemMessage;
  const addSystemReactionFn = dependencies.addSystemReaction ?? addSystemReaction;
  const sleep = dependencies.sleep ?? ((ms: number) => Bun.sleep(ms));
  const buildProviderOrchestrator =
    dependencies.createProviderOrchestrator ?? createProviderOrchestrator;
  const execSyncFn = dependencies.execSync ?? ((command: string) => {
    try {
      const result = Bun.spawnSync(["bash", "-c", command], {
        cwd: process.cwd(),
        timeout: 120_000,
      });
      return {
        status: result.exitCode,
        stdout: result.stdout?.toString() || "",
        stderr: result.stderr?.toString() || "",
      };
    } catch (e) {
      return { status: 1, stdout: "", stderr: String(e) };
    }
  });

  // Superpower: pending verification task to include in restart marker
  let pendingVerificationTask: VerificationTask | null = null;

  if (typeof manager.setProviderOrchestrator === "function") {
    const retryPolicies = parseProviderRetryPoliciesFromEnv(
      process.env.PROVIDER_RETRY_POLICIES_JSON
    );
    manager.setProviderOrchestrator(
      buildProviderOrchestrator({
        retryPolicies,
      })
    );
  }

  const bot = createBot();
  registerMiddleware(bot);
  await registerCommands(bot);
  registerHandlers(bot);

  console.log("=".repeat(50));
  console.log("Claude Telegram Bot - TypeScript Edition");
  console.log("=".repeat(50));
  console.log(`Working directory: ${WORKING_DIR}`);
  console.log(`Allowed users: ${ALLOWED_USERS.length}`);
  console.log("Starting bot...");

  const botInfo = await bot.api.getMe();
  console.log(`Bot started: @${botInfo.username}`);
  if (botInfo.username) {
    setBotUsername(botInfo.username);
  }

  configureScheduler(bot.api, manager);

  const formStore = createFormStore();
  const loadedForms = await formStore.loadForms();
  console.log(`[Startup] Loaded ${loadedForms} pending forms`);

  if (fsOps.existsSync(RESTART_FILE)) {
    try {
      const data = JSON.parse(fsOps.readFileSync(RESTART_FILE, "utf-8")) as {
        chat_id?: number;
        message_id?: number;
        timestamp?: number;
      };
      const age = Date.now() - Number(data.timestamp ?? 0);
      if (age < 30000 && data.chat_id && data.message_id) {
        await bot.api.editMessageText(
          data.chat_id,
          data.message_id,
          "✅ Bot restarted"
        );
      }
      fsOps.unlinkSync(RESTART_FILE);
    } catch (error) {
      console.warn("Failed to update restart message:", error);
      try {
        fsOps.unlinkSync(RESTART_FILE);
      } catch {
        // Ignore cleanup errors.
      }
    }
  }

  // Track whether a restart/crash marker was processed
  let restartMarkerProcessed = false;

  // Inject restart context so Claude knows not to re-execute previous commands
  if (fsOps.existsSync(RESTART_MARKER_FILE)) {
    restartMarkerProcessed = true;
    try {
      const marker = JSON.parse(fsOps.readFileSync(RESTART_MARKER_FILE, "utf-8"));
      const userId = ALLOWED_USERS[0];
      if (userId) {
        const session = manager.getSession(userId);

        // Superpower: auto-verify if verification task was set before SIGTERM
        if (marker.verificationTask) {
          const vt = marker.verificationTask as VerificationTask;
          console.log(`[SUPERPOWER] Running verification: ${vt.command}`);

          const result = execSyncFn(vt.command);
          const passed = result.status === 0;

          if (passed) {
            // SUCCESS: notify telegram
            console.log(`[SUPERPOWER] ✅ Verification PASSED for ${vt.bdTaskId}`);
            try {
              await bot.api.sendMessage(
                userId,
                `✅ **Verification PASSED** [${vt.bdTaskId}]\n\n` +
                  `\`${vt.description}\`\n` +
                  `Command: \`${vt.command}\`\n` +
                  `배포 후 자동 검증 성공.`,
                { parse_mode: "Markdown" }
              );
            } catch (e) {
              console.error(`[SUPERPOWER] Failed to send PASS notification:`, e);
            }
          } else {
            // FAILURE: notify telegram + inject fix request into session
            console.error(`[SUPERPOWER] ❌ Verification FAILED for ${vt.bdTaskId}`);
            const output = (result.stderr || result.stdout || "").slice(0, 500);
            try {
              await bot.api.sendMessage(
                userId,
                `❌ **Verification FAILED** [${vt.bdTaskId}]\n\n` +
                  `\`${vt.description}\`\n` +
                  `Command: \`${vt.command}\`\n` +
                  `Exit code: ${result.status}\n\n` +
                  `\`\`\`\n${output}\n\`\`\`\n\n` +
                  `자동 수정을 시도합니다.`,
                { parse_mode: "Markdown" }
              );
            } catch (e) {
              console.error(`[SUPERPOWER] Failed to send FAIL notification:`, e);
            }

            // Proactive boot: auto-trigger fix via sendMessageStreaming
            const fixPrompt =
              `[SYSTEM] 배포 후 자동 검증 실패. 자동 수정 필요.\n` +
              `Task: ${vt.bdTaskId} (${vt.description})\n` +
              `Command: ${vt.command}\n` +
              `Exit code: ${result.status}\n` +
              `Output:\n${output}\n\n` +
              `이전 세션의 명령(make up, restart 등)은 이미 완료됨. 절대 재실행하지 마세요.\n` +
              `위 검증 실패를 분석하고 코드를 수정하세요.`;
            session.nextQueryContext = { userId, context: fixPrompt };

            // Proactive: auto-start fix without waiting for user message
            try {
              console.log(`[SUPERPOWER] Proactive boot: auto-triggering fix for ${vt.bdTaskId}`);
              await session.sendMessageStreaming(
                fixPrompt,
                async () => {},
                userId,
                "general",
                userId,
              );
            } catch (e) {
              console.error(`[SUPERPOWER] Proactive fix trigger failed:`, e);
            }
          }
        } else {
          // No verification task — determine restart reason from crash marker
          let restartReason = "make up / systemctl restart";
          let restartType: "deploy" | "sigint" | "crash" = "deploy";
          let restartEmoji = "🔄";
          let crashError: string | null = null;

          if (fsOps.existsSync(CRASH_MARKER_FILE)) {
            try {
              const crashData = JSON.parse(fsOps.readFileSync(CRASH_MARKER_FILE, "utf-8"));
              const reason = crashData.reason as string;
              if (reason === "uncaughtException") {
                restartReason = "uncaughtException (프로세스 크래시)";
                restartType = "crash";
                restartEmoji = "💥";
                crashError = crashData.error || null;
              } else if (reason === "unhandledRejection") {
                restartReason = "unhandledRejection (프로세스 크래시)";
                restartType = "crash";
                restartEmoji = "💥";
                crashError = crashData.error || null;
              } else if (reason === "sigint") {
                restartReason = "Ctrl+C (SIGINT)";
                restartType = "sigint";
                restartEmoji = "⏹️";
              } else if (reason === "sigterm") {
                restartReason = "배포/재시작 (SIGTERM)";
                restartType = "deploy";
                restartEmoji = "▶️";
              }
              fsOps.unlinkSync(CRASH_MARKER_FILE);
            } catch {
              // ignore
            }
          }

          let contextMsg =
            `[SYSTEM] 서비스가 방금 재시작되었습니다.\n` +
            `재시작 원인: ${restartEmoji} ${restartReason}\n` +
            `이전 세션의 명령(make up, restart 등)은 이미 완료되었습니다. 절대 재실행하지 마세요.\n` +
            `이전 종료 시각: ${marker.timestamp || "unknown"}`;

          if (crashError) {
            contextMsg += `\n\n크래시 에러:\n${crashError.slice(0, 1000)}`;
          }

          session.nextQueryContext = { userId, context: contextMsg };

          // Send Telegram notification to user about restart type
          try {
            let telegramMsg = `${restartEmoji} **서비스 재시작**\n\n`;
            telegramMsg += `유형: ${restartReason}\n`;
            telegramMsg += `시각: ${marker.timestamp || "unknown"}`;

            if (restartType === "crash" && crashError) {
              telegramMsg += `\n\n\`\`\`\n${crashError.slice(0, 500)}\n\`\`\``;
            }

            await bot.api.sendMessage(userId, telegramMsg, { parse_mode: "Markdown" });
          } catch (notifyErr) {
            console.error("[STARTUP] Failed to send restart notification:", notifyErr);
          }
        }
        console.log("[STARTUP] Restart marker processed");
      }
      fsOps.unlinkSync(RESTART_MARKER_FILE);
    } catch (e) {
      console.warn("[STARTUP] Failed to process restart marker:", e);
      try { fsOps.unlinkSync(RESTART_MARKER_FILE); } catch (cleanupErr) {
        console.error("[STARTUP] Failed to delete restart marker:", cleanupErr);
      }
    }
  }

  // Handle crash marker WITHOUT restart marker — OS killed process (OOM, SIGKILL, etc.)
  // No SIGTERM was caught, so no restart marker exists, but crash marker might.
  if (!restartMarkerProcessed && fsOps.existsSync(CRASH_MARKER_FILE)) {
    restartMarkerProcessed = true;
    try {
      const crashData = JSON.parse(fsOps.readFileSync(CRASH_MARKER_FILE, "utf-8"));
      const reason = crashData.reason as string;
      const userId = ALLOWED_USERS[0];

      if (userId) {
        const session = manager.getSession(userId);
        let reasonLabel = `프로세스 크래시 (${reason})`;
        if (reason === "uncaughtException") reasonLabel = "💥 uncaughtException";
        else if (reason === "unhandledRejection") reasonLabel = "💥 unhandledRejection";

        const errorStr = crashData.error ? `\n\n크래시 에러:\n${String(crashData.error).slice(0, 1000)}` : "";

        session.nextQueryContext = {
          userId,
          context: `[SYSTEM] 서비스가 비정상 종료 후 재시작되었습니다.\n` +
            `종료 원인: ${reasonLabel}\n` +
            `종료 시각: ${crashData.timestamp || "unknown"}` +
            errorStr +
            `\n\n이전 세션의 명령은 이미 완료되었습니다. 절대 재실행하지 마세요.`,
        };

        // Send Telegram notification — OS-level crash (no SIGTERM caught)
        try {
          let telegramMsg = `🔥 **비정상 종료 후 재시작**\n\n`;
          telegramMsg += `원인: ${reasonLabel}\n`;
          telegramMsg += `시각: ${crashData.timestamp || "unknown"}`;
          if (crashData.error) {
            telegramMsg += `\n\n\`\`\`\n${String(crashData.error).slice(0, 500)}\n\`\`\``;
          }
          await bot.api.sendMessage(userId, telegramMsg, { parse_mode: "Markdown" });
        } catch {
          // best effort
        }
      }

      fsOps.unlinkSync(CRASH_MARKER_FILE);
      console.log(`[STARTUP] Crash marker processed: reason=${reason}`);
    } catch {
      try { fsOps.unlinkSync(CRASH_MARKER_FILE); } catch {}
    }
  }

  // Handle startup WITHOUT any markers — OS reboot, OOM kill, SIGKILL, power loss
  if (!restartMarkerProcessed) {
    // Check if there was a previous session (if session data exists but no markers = unexpected restart)
    const userId = ALLOWED_USERS[0];
    if (userId) {
      const session = manager.getSession(userId);
      if (session.totalQueries > 0) {
        // Had previous session but no markers = OS-level kill (OOM, SIGKILL, reboot)
        session.nextQueryContext = {
          userId,
          context: `[SYSTEM] 서비스가 재시작되었습니다.\n` +
            `재시작 원인: 🖥️ OS 재시작 또는 프로세스 강제 종료 (SIGKILL/OOM)\n` +
            `마커 파일 없음 — SIGTERM이 캐치되지 않았으므로 OS 레벨 종료로 추정됩니다.\n` +
            `이전 세션의 명령은 이미 완료되었습니다. 절대 재실행하지 마세요.`,
        };

        try {
          await bot.api.sendMessage(
            userId,
            `🖥️ **OS 재시작/강제 종료 후 복구**\n\n` +
            `SIGTERM 마커가 없어 OS 레벨 종료로 추정됩니다.\n` +
            `(OOM kill, SIGKILL, 서버 재부팅 등)`,
            { parse_mode: "Markdown" }
          );
        } catch {
          // best effort
        }
      }
    }
  }

  const startTs = new Date().toISOString();
  console.log(`\n[${startTs}] ========== BOT STARTUP ==========`);
  console.log(`[STARTUP] PID: ${process.pid}`);
  console.log(`[STARTUP] Working dir: ${WORKING_DIR}`);
  console.log(`[STARTUP] Allowed users: ${ALLOWED_USERS.length}`);

  const runner = startRunner(bot);
  console.log("[STARTUP] Bot runner started");

  const stopRunner = () => {
    console.log("[SHUTDOWN] Step 1: Stopping scheduler...");
    stopScheduler();
    console.log("[SHUTDOWN] Step 2: Saving all sessions...");
    const stats = manager.getGlobalStats();
    console.log(
      `[SHUTDOWN] Sessions to save: ${stats.totalSessions}, Total queries: ${stats.totalQueries}`
    );
    manager.saveAllSessions();
    console.log("[SHUTDOWN] Step 3: Sessions saved");
    if (runner.isRunning()) {
      console.log("[SHUTDOWN] Step 4: Stopping bot runner...");
      runner.stop();
      console.log("[SHUTDOWN] Step 5: Bot runner stopped");
    } else {
      console.log("[SHUTDOWN] Step 4: Bot runner already stopped");
    }
  };

  const saveShutdownContext = async (): Promise<void> => {
    console.log("\n[CONTEXT-SAVE] ========== SAVING CONTEXT ==========");
    const userId = ALLOWED_USERS[0];

    try {
      const saveDir = `${WORKING_DIR}/docs/tasks/save`;
      fsOps.mkdirSync(saveDir, { recursive: true });

      const timestamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, -5);
      const saveFile = `${saveDir}/restart-context-${timestamp}.md`;
      const now = new Date().toLocaleString("ko-KR", { timeZone: "Asia/Seoul" });
      const stats = manager.getGlobalStats();

      let contextInfo = "";
      let ctxPct = "0";
      if (userId) {
        const session = manager.getSession(userId);
        const effectiveMax = session.actualContextMax ?? session.contextWindowSize;
        ctxPct = effectiveMax > 0
          ? ((session.currentContextTokens / effectiveMax) * 100).toFixed(1)
          : "?";
        contextInfo = `Context: ${ctxPct}% (${session.currentContextTokens.toLocaleString()}/${effectiveMax.toLocaleString()} tokens)`;
      }

      const content = [
        `# Restart Context - ${now}`,
        ``,
        `## Message from Previous Session`,
        ``,
        `Gracefully shut down via make up. Sessions will be restored automatically.`,
        ``,
        `Active sessions: ${stats.totalSessions}`,
        contextInfo,
        `Total queries: ${stats.totalQueries}`,
        ``,
        `---`,
        `*Auto-generated by SIGTERM handler*`,
      ].join("\n");

      fsOps.writeFileSync(saveFile, content, "utf-8");
      console.log(`[CONTEXT-SAVE] ✅ File saved: ${saveFile}`);

      if (userId) {
        const shortFile = saveFile.replace(WORKING_DIR, ".");
        await Promise.race([
          sendSystemMessageFn(
            { api: bot.api, chatId: userId },
            `**Context Saved**\n\n` +
              `📁 \`${shortFile}\`\n` +
              `📊 Context: ${ctxPct}%\n` +
              `🔢 Queries: ${stats.totalQueries}`,
            { parse_mode: "Markdown" }
          ),
          new Promise<null>((_, reject) =>
            setTimeout(() => reject(new Error("Timeout")), 3000)
          ),
        ]).catch((error) => {
          console.error(`[CONTEXT-SAVE] Failed to notify user: ${error}`);
          return null;
        });
      }
    } catch (error) {
      console.error(`[CONTEXT-SAVE] ❌ Failed to save: ${error}`);
      if (userId) {
        await sendSystemMessageFn(
          { api: bot.api, chatId: userId },
          `**Context Save Failed**\n\n⚠️ ${String(error).slice(0, 200)}`,
          { parse_mode: "Markdown" }
        ).catch(() => {});
      }
    }
  };

  const sendShutdownMessage = async (): Promise<void> => {
    if (ALLOWED_USERS.length === 0) {
      return;
    }

    const userId = ALLOWED_USERS[0]!;
    const session = manager.getSession(userId);
    const now = new Date();

    let duration = "N/A";
    let startTimeStr = "N/A";
    const endTimeStr = now.toLocaleTimeString("ko-KR", {
      timeZone: "Asia/Seoul",
      hour12: true,
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });

    if (session.sessionStartTime) {
      startTimeStr = session.sessionStartTime.toLocaleTimeString("ko-KR", {
        timeZone: "Asia/Seoul",
        hour12: true,
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
      });
      const diffMs = now.getTime() - session.sessionStartTime.getTime();
      const hours = Math.floor(diffMs / 3600000);
      const minutes = Math.floor((diffMs % 3600000) / 60000);
      const seconds = Math.floor((diffMs % 60000) / 1000);
      duration =
        hours > 0
          ? `${hours}h ${minutes}m`
          : `${minutes}:${String(seconds).padStart(2, "0")}`;
    }

    const contextTokens = session.currentContextTokens;
    const contextSize = session.actualContextMax ?? session.contextWindowSize;
    const contextPct =
      (contextTokens > 0 && contextSize > 0) ? ((contextTokens / contextSize) * 100).toFixed(1) : "?";
    const toolStats = session.formatToolStats();

    const lines = [
      `${SYS_MSG_PREFIX} ━━━━━━━━━━━━━━━━━━━━━━`,
      "🔄 서비스를 재시작합니다.",
      `⏰ ${startTimeStr} → ${endTimeStr} (${duration})`,
      `📊 Context: ${contextPct}% (${contextTokens.toLocaleString()}/${contextSize.toLocaleString()} tokens)`,
      `📈 Queries: ${session.totalQueries} | Tokens: ${(session.totalInputTokens + session.totalOutputTokens).toLocaleString()}`,
    ];
    if (toolStats) {
      lines.push(`🔧 ${toolStats}`);
    }
    lines.push("━━━━━━━━━━━━━━━━━━━━━━");

    try {
      const shutdownMsg = await Promise.race([
        bot.api.sendMessage(userId, lines.join("\n"), { parse_mode: "HTML" }),
        new Promise<never>((_, reject) =>
          setTimeout(() => reject(new Error("Timeout")), 5000)
        ),
      ]);

      if (shutdownMsg?.message_id) {
        addSystemReactionFn(bot.api, userId, shutdownMsg.message_id).catch(() => {});
      }
    } catch (error) {
      console.error("[SHUTDOWN-MSG] ❌ Failed:", error);
    }
  };

  const savePendingSteering = () => {
    const userId = ALLOWED_USERS[0];
    if (!userId) return;

    const session = manager.getSession(userId);
    if (!session.hasSteeringMessages()) return;

    const count = session.getSteeringCount();
    const content = session.consumeSteering();
    if (!content) return;

    const steeringFile = "/tmp/soma-pending-steering.json";
    fsOps.writeFileSync(
      steeringFile,
      JSON.stringify({ count, content, timestamp: new Date().toISOString() }),
      "utf-8"
    );
    console.log(
      `[SIGTERM] Saved ${count} pending steering message(s) to ${steeringFile}`
    );
  };

  const handleSigterm = async (): Promise<void> => {
    const ts = new Date().toISOString();
    console.log(`\n[${ts}] ========== SIGTERM RECEIVED ==========`);
    console.log(
      "[SIGTERM] Graceful shutdown initiated (likely from make up or systemctl)"
    );
    console.log("[SIGTERM] PID:", process.pid);

    savePendingSteering();
    await sendShutdownMessage();
    await saveShutdownContext();

    // Write restart marker so next boot injects a system message.
    // Without this, Claude Code session resumes with "make up 해줘"
    // still in context and re-executes it → infinite restart loop.
    try {
      const markerData: Record<string, unknown> = {
        timestamp: new Date().toISOString(),
        pid: process.pid,
      };

      // Superpower: check for verification task — either set in-process
      // or written to /tmp/soma-verification-task.json by external tool (e.g., Claude Code Bash)
      const VERIFICATION_TASK_FILE = "/tmp/soma-verification-task.json";
      if (!pendingVerificationTask && fsOps.existsSync(VERIFICATION_TASK_FILE)) {
        try {
          pendingVerificationTask = JSON.parse(
            fsOps.readFileSync(VERIFICATION_TASK_FILE, "utf-8")
          ) as VerificationTask;
          console.log(`[SIGTERM] Loaded verification task from file: ${pendingVerificationTask.bdTaskId}`);
          fsOps.unlinkSync(VERIFICATION_TASK_FILE);
        } catch (e) {
          console.warn("[SIGTERM] Failed to read verification task file:", e);
        }
      }

      if (pendingVerificationTask) {
        markerData.verificationTask = pendingVerificationTask;
        console.log(`[SIGTERM] Including verification task: ${pendingVerificationTask.bdTaskId}`);
      }
      fsOps.writeFileSync(
        RESTART_MARKER_FILE,
        JSON.stringify(markerData),
        "utf-8"
      );
      console.log("[SIGTERM] Restart marker written");
    } catch (e) {
      console.error("[SIGTERM] Failed to write restart marker:", e);
    }

    stopRunner();
    await sleep(1000);
  };

  const setVerificationTask = (task: VerificationTask | null): void => {
    pendingVerificationTask = task;
    if (task) {
      console.log(`[SUPERPOWER] Verification task set: ${task.bdTaskId} — ${task.description}`);
    } else {
      console.log("[SUPERPOWER] Verification task cleared");
    }
  };

  // Best-effort crash notification — called from uncaughtException/unhandledRejection
  // before process dies. Synchronous Telegram call via fetch (no await needed).
  const notifyCrash = (reason: string, error?: unknown): void => {
    const userId = ALLOWED_USERS[0];
    if (!userId) return;

    const errorStr = error instanceof Error
      ? `${error.name}: ${error.message}`
      : error != null ? String(error).slice(0, 500) : "unknown";

    const reasonLabel =
      reason === "uncaughtException" ? "💥 Uncaught Exception" :
      reason === "unhandledRejection" ? "💥 Unhandled Promise Rejection" :
      `💥 Crash (${reason})`;

    const text =
      `${reasonLabel}\n\n` +
      `\`\`\`\n${errorStr.slice(0, 800)}\n\`\`\`\n\n` +
      `프로세스가 종료됩니다. systemd가 10초 후 재시작합니다.`;

    // Fire-and-forget — process is about to die
    bot.api.sendMessage(userId, text, { parse_mode: "Markdown" }).catch(() => {});
  };

  return {
    bot,
    runner,
    formStore,
    stopRunner,
    handleSigterm,
    setVerificationTask,
    notifyCrash,
  };
}

import { existsSync, readFileSync, writeFileSync } from "fs";
import type { Context } from "grammy";
import { WORKING_DIR } from "../../config";
import { MODEL_DISPLAY_NAMES, getModelForContext } from "../../config/model";
import type { ClaudeSession } from "../../core/session/session";
import { Reactions } from "../../constants/reactions";
import { fetchClaudeUsage } from "../../usage";
import { auditLog } from "../../utils/audit";
import { addTimestamp } from "../../utils/interrupt";
import { startTypingIndicator } from "../../utils/typing";
import {
  formatErrorForLog,
  formatErrorForUser,
  formatRateLimitForUser,
  handleAbortError,
  isAbortError,
  isRateLimitError,
  isSonnetAvailable,
} from "../../utils/error-classification";
import { isReentrancyError } from "./query-flow-guard";
import { sendSystemMessage } from "../../utils/system-message";
import { formatSteeringMessages } from "../../core/session/session-helpers";
import {
  StreamingState,
  cleanupToolMessages,
  createStatusCallback,
} from "../streaming";

export interface QueryFlowParams {
  ctx: Context;
  session: ClaudeSession;
  message: string;
  chatId: number;
  userId: number;
  username: string;
  deliverInboundReaction: (reaction: string) => Promise<void>;
}

// Marker returned by interrupt-flow when steering messages remain in buffer.
// When detected, skip the initial Claude query and go straight to auto-continue.
const INTERRUPT_STEERING_MARKER = "[시스템: 인터럽트 후 대기 메시지 처리]";

export async function runQueryFlow(params: QueryFlowParams): Promise<void> {
  const { ctx, session, message, chatId, userId, username, deliverInboundReaction } =
    params;
  // Don't pollute lastMessage with synthetic interrupt marker (breaks /retry)
  const isInterruptDrain = message === INTERRUPT_STEERING_MARKER;
  if (!isInterruptDrain) {
    session.lastMessage = message;
  }
  const messageWithTimestamp = addTimestamp(message);
  const stopProcessing = session.startProcessing();

  try {
    await deliverInboundReaction(Reactions.PROCESSING);
  } catch (e) { console.warn("[REACT] deliverInboundReaction failed:", e); }

  const typing = startTypingIndicator(ctx);
  let state = new StreamingState();
  let statusCallback = await createStatusCallback(ctx, state, session);
  const MAX_RETRIES = 1;

  try {
    // When interrupt drains steering, skip initial query — go straight to auto-continue loop
    if (isInterruptDrain) {
      console.log("[QUERY-FLOW] Interrupt drain mode: skipping initial query, entering auto-continue");
    }

    for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
      try {
        if (!isInterruptDrain) {
          const response = await session.sendMessageStreaming(
            messageWithTimestamp,
            statusCallback,
            chatId,
            "general",
            userId
          );

          await auditLog(userId, username, "TEXT", message, response);

          try {
            await deliverInboundReaction(Reactions.COMPLETE);
          } catch (e) { console.warn("[REACT] complete reaction failed:", e); }
        } // end if (!isInterruptDrain)

        const MAX_AUTO_CONTINUE_ROUNDS = 5;
        let autoContinueRound = 0;

        // Fix soma-uqb9: For text-only responses, PostToolUse hook never fires,
        // so messages remain in steeringBuffer (not tracked via injectedSteering).
        // Previously we called trackBufferedMessagesForInjection() here, but that
        // COPIES to injectedSteering without clearing the buffer. Then
        // restoreInjectedSteering() merges injected BACK into the still-populated
        // buffer, duplicating every message (3 messages → 6).
        //
        // Fix: Skip the track→restore round-trip entirely for text-only responses.
        // The auto-continue loop below already consumes directly from the buffer.
        // For tool-use responses, postToolUseHook handles track+consume correctly.

        // Fix #24: If user issued /stop, abort was suppressed in sendMessageStreaming
        // but we must NOT continue processing steering messages.
        if (session.wasStoppedByUser) {
          console.log("[AUTO-CONTINUE] Skipping — user issued /stop");
          const discarded = session.extractSteeringMessages();
          if (discarded.length > 0) {
            console.log(`[AUTO-CONTINUE] Discarded ${discarded.length} steering message(s) due to /stop`);
          }
          break;
        }

        while (true) {
          // Fix #24: Check FIRST if user stopped — before any buffer work
          if (session.wasStoppedByUser) {
            console.log(`[AUTO-CONTINUE] Breaking loop — user issued /stop during round ${autoContinueRound}`);
            session.extractSteeringMessages(); // drain both stores
            break;
          }

          // Restore any injected messages from tool-use hooks back to buffer
          // (only relevant when postToolUseHook ran during the query)
          const bufferBeforeRestore = session.getSteeringCount();
          const restoredCount = session.restoreInjectedSteering();
          const bufferAfterRestore = session.getSteeringCount();
          console.log(
            `[STEERING DEBUG] Round ${autoContinueRound}: Before restore: ${bufferBeforeRestore}, Restored: ${restoredCount}, After: ${bufferAfterRestore}`
          );

          const hasSteering = session.hasSteeringMessages();
          console.log(
            `[AUTO-CONTINUE] Round ${autoContinueRound}: hasSteeringMessages() = ${hasSteering}, buffer count = ${session.getSteeringCount()}`
          );

          if (!hasSteering) {
            if (autoContinueRound === 0) {
              console.log("[AUTO-CONTINUE] No pending steering messages");
            } else {
              console.log(
                `[AUTO-CONTINUE] Drained all steering after ${autoContinueRound} round(s)`
              );
            }
            break;
          }

          if (autoContinueRound >= MAX_AUTO_CONTINUE_ROUNDS) {
            console.warn(
              `[AUTO-CONTINUE] Hit max rounds (${MAX_AUTO_CONTINUE_ROUNDS}), stopping. Remaining buffer: ${session.getSteeringCount()}`
            );
            break;
          }

          autoContinueRound++;
          const steeringCount = session.getSteeringCount();
          console.log(
            `[AUTO-CONTINUE] Round ${autoContinueRound}: Processing ${steeringCount} pending message(s)`
          );

          const steeringResult = session.consumeSteeringWithIds();
          console.log(
            `[AUTO-CONTINUE] Round ${autoContinueRound}: Consumed: "${steeringResult?.formatted.slice(0, 100)}..."`
          );

          if (!steeringResult) {
            console.warn(
              "[AUTO-CONTINUE] consumeSteeringWithIds returned null despite hasSteering=true"
            );
            break;
          }

          const { formatted: steeringContent, messageIds: steeringMsgIds } = steeringResult;

          // Mark consumed steering messages as DELIVERED (👌 → 🙏)
          for (const msgId of steeringMsgIds) {
            try {
              await ctx.api.setMessageReaction(chatId, msgId, [
                { type: "emoji", emoji: Reactions.STEERING_DELIVERED },
              ]);
            } catch {
              // Rate limited or not allowed — non-critical
            }
          }

          try {
            await sendSystemMessage(
              ctx,
              `💬 <i>대기 메시지 ${steeringCount}개 처리 중...</i>`,
              {
                parse_mode: "HTML",
              }
            );
          } catch (e) { console.warn("[SYSTEM-MSG] steering notification failed:", e); }

          const followUpMessage = `[이전 응답 중 보낸 메시지 - 지금 처리합니다]\n${steeringContent}`;

          const followUpState = new StreamingState();
          const followUpCallback = await createStatusCallback(
            ctx,
            followUpState,
            session
          );

          try {
            console.log(
              `[AUTO-CONTINUE] Round ${autoContinueRound}: Sending follow-up query...`
            );
            const followUpResponse = await session.sendMessageStreaming(
              followUpMessage,
              followUpCallback,
              chatId,
              "general",
              userId
            );
            console.log(
              `[AUTO-CONTINUE] Round ${autoContinueRound}: Follow-up complete, response length: ${followUpResponse.length}`
            );

            // Mark consumed steering messages as COMPLETE (🙏 → 👍)
            for (const msgId of steeringMsgIds) {
              try {
                await ctx.api.setMessageReaction(chatId, msgId, [
                  { type: "emoji", emoji: Reactions.COMPLETE },
                ]);
              } catch {}
            }

            await auditLog(
              userId,
              username,
              "STEERING_FOLLOWUP",
              steeringContent,
              followUpResponse
            );
            await Bun.sleep(500);
          } catch (followUpError) {
            // Fix #24: Distinguish user-initiated stop from real failures
            if (session.wasStoppedByUser || isAbortError(followUpError)) {
              console.log(
                `[AUTO-CONTINUE] Round ${autoContinueRound}: Follow-up stopped by user`
              );
              break;
            }

            console.error(
              `[AUTO-CONTINUE] Round ${autoContinueRound}: Follow-up FAILED:`,
              followUpError
            );

            // Mark consumed steering messages as ERROR (🙏 → 💩)
            for (const msgId of steeringMsgIds) {
              try {
                await ctx.api.setMessageReaction(chatId, msgId, [
                  { type: "emoji", emoji: Reactions.ERROR_MODEL },
                ]);
              } catch {}
            }

            await sendSystemMessage(
              ctx,
              "⚠️ 대기 중인 메시지 처리 실패. 다시 보내주세요."
            );
            break;
          }
        }

        if (session.needsSave) {
          const currentTokens = session.currentContextTokens;
          const windowSize = session.actualContextMax ?? session.contextWindowSize;
          const percentage = windowSize > 0 ? ((currentTokens / windowSize) * 100).toFixed(1) : "?";
          await sendSystemMessage(
            ctx,
            `⚠️ **Context Limit Approaching**\n\n` +
              `Current: ${currentTokens.toLocaleString()} / ${windowSize.toLocaleString()} tokens (${percentage}%)\n\n` +
              `Initiating automatic save...`,
            { parse_mode: "Markdown" }
          );

          try {
            const saveResponse = await session.sendMessageStreaming(
              "Context limit reached. Execute: Skill tool with skill='oh-my-claude:save'",
              async () => {},
              chatId,
              "general",
              userId
            );

            const saveIdMatch = saveResponse.match(
              /Saved to:.*?\/docs\/tasks\/save\/(\d{8}_\d{6})\//
            );
            if (saveIdMatch && saveIdMatch[1]) {
              const saveId = saveIdMatch[1];
              if (!/^\d{8}_\d{6}$/.test(saveId)) {
                console.error(`Invalid save ID format: ${saveId}`);
                console.error(`Full response: ${saveResponse}`);
                await ctx.reply(
                  `❌ Save ID validation failed: ${saveId}\n\nFull response logged.`
                );
                break;
              }

              const saveIdFile = `${WORKING_DIR}/.last-save-id`;
              writeFileSync(saveIdFile, saveId, "utf-8");

              if (
                !existsSync(saveIdFile) ||
                readFileSync(saveIdFile, "utf-8").trim() !== saveId
              ) {
                const error = "Failed to persist save ID - file not written correctly";
                console.error(error);
                await ctx.reply(`❌ ${error}`);
                throw new Error(error);
              }

              console.log(`✅ Save ID captured & verified: ${saveId} → ${saveIdFile}`);
              console.log("[TELEMETRY] auto_save_success", {
                saveId,
                contextTokens: currentTokens,
                timestamp: new Date().toISOString(),
              });

              await sendSystemMessage(
                ctx,
                `✅ **Context Saved**\n\n` +
                  `Save ID: \`${saveId}\`\n\n` +
                  `Please run: \`make up\` to restart with restored context.`,
                { parse_mode: "Markdown" }
              );
            } else {
              console.warn(
                "Failed to parse save_id from response:",
                saveResponse.slice(0, 200)
              );
              await ctx.reply(
                `⚠️ Save completed but couldn't parse save ID. Response: ${saveResponse.slice(0, 200)}`
              );
            }
          } catch (error) {
            console.error("CRITICAL: Auto-save failed:", error);
            console.error("Stack:", error instanceof Error ? error.stack : "N/A");

            const errorStr = String(error);
            const sanitized = errorStr.replace(
              process.env.HOME || "/home/zhugehyuk",
              "~"
            );

            await sendSystemMessage(
              ctx,
              `🚨 **CRITICAL: Auto-Save Failed**\n\n` +
                `Error: ${sanitized.slice(0, 300)}\n\n` +
                `⚠️ **YOUR WORK IS NOT SAVED**\n\n` +
                `Do NOT restart. Try manual: /oh-my-claude:save`,
              { parse_mode: "Markdown" }
            );
          }
        }

        break;
      } catch (error) {
        if (isReentrancyError(error)) {
          console.warn(`[QUERY] Re-entrancy guard hit, buffering as steering: "${message.slice(0, 50)}"`);
          const msgId = ctx.message?.message_id ?? 0;
          session.addSteering(message, msgId);
          try {
            await sendSystemMessage(ctx, "⏳ 이전 요청 처리 중입니다. 메시지가 대기열에 추가되었습니다.");
          } catch (e) { console.warn("[SYSTEM-MSG] steering queue notification failed:", e); }
          return;
        }

        const errorStr = String(error);

        // Auto-retry on expired session ID (soma-nok6)
        if (errorStr.includes("SESSION_EXPIRED") && attempt < MAX_RETRIES) {
          console.log(`[SESSION-RESUME] Session expired, auto-retrying as new session (attempt ${attempt + 1})`);
          cleanupToolMessages(ctx, state.toolMessages);
          state.cleanup();
          state = new StreamingState();
          statusCallback = await createStatusCallback(ctx, state, session);
          continue;
        }

        const isClaudeCodeCrash = errorStr.includes("exited with code");

        cleanupToolMessages(ctx, state.toolMessages);

        if (isClaudeCodeCrash) {
          const exitCodeMatch = errorStr.match(/exited with code (\d+)/);
          const exitCode = exitCodeMatch ? parseInt(exitCodeMatch[1], 10) : null;
          console.error(`[CRASH] Claude Code crashed: exit_code=${exitCode}, error=${errorStr}`);

          // Preserve steering messages before kill() clears them
          const killResult = await session.kill();
          session.clearStopRequested();

          // Preserve lost steering messages as context for next query (user-bound)
          if (killResult.count > 0) {
            const preserved = formatSteeringMessages(killResult.messages);
            const existingCtx = session.nextQueryContext?.userId === userId
              ? session.nextQueryContext.context
              : "";
            session.nextQueryContext = {
              userId,
              context: existingCtx
                ? `${existingCtx}\n[CRASH RECOVERY - ${killResult.count} message(s)]\n${preserved}\n[END RECOVERY]`
                : `[CRASH RECOVERY - ${killResult.count} message(s)]\n${preserved}\n[END RECOVERY]`,
            };
            console.warn(
              `[CRASH-RECOVERY] Preserved ${killResult.count} steering message(s) as nextQueryContext`
            );
          }

          // Preserve user's original message as context for next interaction
          // NOTE: We do NOT auto-retry because tools may have already executed
          // during the crashed turn — replaying would cause non-idempotent side effects.
          if (!isInterruptDrain) {
            const existingCtx = session.nextQueryContext?.userId === userId
              ? session.nextQueryContext.context
              : "";
            const crashContext = `[SYSTEM: Previous query crashed (exit code ${exitCode ?? "unknown"}). The user's message below was being processed when the crash occurred.]\n${message}`;
            session.nextQueryContext = {
              userId,
              context: existingCtx
                ? `${existingCtx}\n${crashContext}`
                : crashContext,
            };
          }

          const shortError = errorStr.slice(0, 800);
          try {
            await sendSystemMessage(
              ctx,
              `💥 **Claude Code crashed** (exit ${exitCode ?? "?"})\n\n` +
                `\`\`\`\n${shortError}\n\`\`\`\n\n` +
                `세션 초기화됨. 다음 메시지에 이전 문맥이 자동 포함됩니다.` +
                (killResult.count > 0 ? `\n⚠️ 대기 중이던 ${killResult.count}개 메시지도 보존됨.` : ""),
              { parse_mode: "Markdown" }
            );
          } catch (notifyErr) {
            console.warn("[CRASH-RECOVERY] Failed to notify user:", notifyErr);
          }
          break;
        }

        const rateLimitInfo = isRateLimitError(error);
        if (rateLimitInfo.isRateLimit) {
          console.log(`[RATE-LIMIT] Detected: bucket=${rateLimitInfo.bucket}`);
          session.rateLimitState.consecutiveFailures++;

          const usage = await fetchClaudeUsage(10);
          const richMessage = await formatRateLimitForUser(error, usage);

          if (
            session.rateLimitState.cooldownUntil &&
            Date.now() < session.rateLimitState.cooldownUntil
          ) {
            await ctx.reply(
              richMessage + "\n\n🛑 연속 실패로 대기 중. 잠시 후 다시 시도해주세요."
            );
            break;
          }

          if (session.rateLimitState.consecutiveFailures >= 3) {
            session.rateLimitState.cooldownUntil = Date.now() + 5 * 60 * 1000;
            await ctx.reply(
              richMessage + "\n\n🛑 연속 3회 실패. 5분 후 다시 시도해주세요."
            );
            break;
          }

          // Only attempt Sonnet fallback if:
          // 1. No temporary override is active
          // 2. Sonnet quota is available
          // 3. Current effective model is NOT already Sonnet (e.g. user switched via /model)
          const currentEffectiveModel = session.temporaryModelOverride ?? getModelForContext("general");
          const alreadyOnSonnet = currentEffectiveModel === "claude-sonnet-4-5-20250929";
          if (!session.temporaryModelOverride && !alreadyOnSonnet && usage && isSonnetAvailable(usage)) {
            const sonnetModel = "claude-sonnet-4-5-20250929" as const;
            session.temporaryModelOverride = sonnetModel;

            if (usage.five_hour?.resets_at) {
              session.rateLimitState.opusResetsAt = usage.five_hour.resets_at;
            }

            const sonnetPct = usage.seven_day_sonnet
              ? `${Math.round(usage.seven_day_sonnet.utilization * 100)}%`
              : "?";

            await sendSystemMessage(
              ctx,
              richMessage +
                `\n\n💡 Sonnet 사용량 ${sonnetPct} → 자동 전환합니다.` +
                `\n🔄 메시지 재전송 중...`
            );

            state.cleanup();
            state = new StreamingState();
            statusCallback = await createStatusCallback(ctx, state, session);

            try {
              const retryResponse = await session.sendMessageStreaming(
                messageWithTimestamp,
                statusCallback,
                chatId,
                "general",
                userId
              );
              await auditLog(userId, username, "TEXT_FALLBACK", message, retryResponse);
              try {
                await deliverInboundReaction(Reactions.COMPLETE);
              } catch (e) { console.warn("[REACT] fallback complete reaction failed:", e); }

              const fallbackModel = session.temporaryModelOverride;
              const modelName = fallbackModel
                ? MODEL_DISPLAY_NAMES[fallbackModel] || fallbackModel
                : "Sonnet";
              await sendSystemMessage(
                ctx,
                `✅ ${modelName}으로 응답 완료. Opus 복구 시 자동 전환됩니다.`
              );
              session.rateLimitState.consecutiveFailures = 0;
              break;
            } catch (retryError) {
              console.error("[RATE-LIMIT] Sonnet fallback also failed:", retryError);
              session.rateLimitState.consecutiveFailures++;
              const retryRateLimitInfo = isRateLimitError(retryError);
              if (retryRateLimitInfo.isRateLimit) {
                const retryUsage = await fetchClaudeUsage(10);
                const retryMessage = await formatRateLimitForUser(
                  retryError,
                  retryUsage
                );
                await ctx.reply(
                  retryMessage + "\n\n🛑 Sonnet도 한도 초과. 잠시 후 다시 시도해주세요."
                );
              } else {
                await ctx.reply(formatErrorForUser(retryError));
              }
              break;
            }
          }

          await ctx.reply(richMessage);
          break;
        }

        console.error(formatErrorForLog(error));

        // User abort: skip steering preservation — user wants to STOP, not continue
        if (isAbortError(error)) {
          console.log("[QUERY-FLOW] User abort detected — skipping steering preservation");
          // Drain both steeringBuffer and injectedSteeringDuringQuery (fix #32)
          const discarded = session.extractSteeringMessages();
          if (discarded.length > 0) {
            console.log(`[QUERY-FLOW] Discarded ${discarded.length} steering message(s) due to user abort`);
          }
          await handleAbortError(ctx, error, session);
          break;
        }

        // Drain BOTH steeringBuffer and injectedSteeringDuringQuery (fix #32)
        const lostMessages = session.extractSteeringMessages();
        if (lostMessages.length > 0) {
          const preserved = formatSteeringMessages(lostMessages);
          const existingCtx = session.nextQueryContext?.userId === userId
            ? session.nextQueryContext.context
            : "";
          session.nextQueryContext = {
            userId,
            context: existingCtx
              ? `${existingCtx}\n[ERROR RECOVERY - ${lostMessages.length} message(s)]\n${preserved}\n[END RECOVERY]`
              : `[ERROR RECOVERY - ${lostMessages.length} message(s)]\n${preserved}\n[END RECOVERY]`,
          };
          console.warn(
            `[STEERING] Preserved ${lostMessages.length} message(s) as nextQueryContext due to error`
          );
          try {
            await ctx.reply(
              `⚠️ 에러 발생. 대기 중이던 ${lostMessages.length}개 메시지가 다음 요청에 자동 포함됩니다.`
            );
          } catch (notifyError) {
            console.error("[STEERING] Failed to notify user of error recovery:", notifyError);
          }
        }

        if (!(await handleAbortError(ctx, error, session))) {
          try {
            await deliverInboundReaction(Reactions.ERROR_MODEL);
          } catch (e) { console.warn("[REACT] error reaction failed:", e); }
          await ctx.reply(formatErrorForUser(error));
        }
        break;
      }
    }
  } finally {
    state.cleanup();
    stopProcessing();
    typing.stop();
  }
}

/**
 * Unit tests for SteeringManager — specifically extractSteeringMessages()
 * which must recover both steeringBuffer AND injectedSteeringDuringQuery.
 *
 * Covers fix for: https://github.com/2lab-ai/soma/issues/32
 */
import { describe, test, expect, beforeEach } from "bun:test";
import { SteeringManager } from "./steering-manager";

const MAX_STEERING = 10;
const RECOVERY_TIMEOUT = 60_000;

function makeManager(): SteeringManager {
  return new SteeringManager(MAX_STEERING, RECOVERY_TIMEOUT);
}

describe("SteeringManager.extractSteeringMessages", () => {
  let mgr: SteeringManager;

  beforeEach(() => {
    mgr = makeManager();
  });

  test("returns empty array when nothing buffered", () => {
    expect(mgr.extractSteeringMessages()).toEqual([]);
  });

  test("returns steeringBuffer messages and clears buffer", () => {
    mgr.addSteering("msg1", 1);
    mgr.addSteering("msg2", 2);

    const extracted = mgr.extractSteeringMessages();
    expect(extracted).toHaveLength(2);
    expect(extracted[0].content).toBe("msg1");
    expect(extracted[1].content).toBe("msg2");

    // Buffer should be empty after extraction
    expect(mgr.extractSteeringMessages()).toEqual([]);
  });

  test("returns injectedSteeringDuringQuery messages (issue #32 fix)", () => {
    // Simulate: messages added, then tracked for injection (PostToolUse hook),
    // then buffer consumed by auto-continue → injectedSteeringDuringQuery has
    // messages but steeringBuffer is empty.
    mgr.addSteering("injected1", 10, "Bash");
    mgr.addSteering("injected2", 11, "Read");
    mgr.trackBufferedMessagesForInjection();
    mgr.consumeSteering(); // auto-continue consumes the buffer

    // At this point: steeringBuffer=[], injectedSteeringDuringQuery=[msg10,msg11]
    // hasSteeringMessages() now checks both stores (fix #32)
    expect(mgr.hasSteeringMessages()).toBe(true);

    const extracted = mgr.extractSteeringMessages();
    expect(extracted).toHaveLength(2);
    expect(extracted[0].content).toBe("injected1");
    expect(extracted[0].receivedDuringTool).toBe("Bash");
    expect(extracted[1].content).toBe("injected2");
    expect(extracted[1].receivedDuringTool).toBe("Read");
  });

  test("returns combined messages from both stores without duplicates", () => {
    // msg1 injected, msg2 still in buffer → both recovered, no duplication
    mgr.addSteering("old-injected", 20, "Bash");
    mgr.trackBufferedMessagesForInjection();
    // Don't consume — so msg 20 is in BOTH injected and buffer
    mgr.addSteering("new-buffered", 21);

    const extracted = mgr.extractSteeringMessages();
    // msg 20 should appear once (from injected), msg 21 from buffer
    expect(extracted).toHaveLength(2);
    expect(extracted.map((m) => m.messageId)).toEqual([20, 21]);
  });

  test("deduplicates messages present in both stores by messageId", () => {
    mgr.addSteering("same-msg", 30, "Bash");
    mgr.trackBufferedMessagesForInjection();
    // msg 30 is now in BOTH injectedSteeringDuringQuery AND steeringBuffer

    const extracted = mgr.extractSteeringMessages();
    expect(extracted).toHaveLength(1);
    expect(extracted[0].messageId).toBe(30);
    expect(extracted[0].content).toBe("same-msg");
  });

  test("clears both stores after extraction", () => {
    mgr.addSteering("a", 40);
    mgr.trackBufferedMessagesForInjection();
    mgr.addSteering("b", 41);

    mgr.extractSteeringMessages();

    // Both stores empty
    expect(mgr.extractSteeringMessages()).toEqual([]);
    expect(mgr.getInjectedCount()).toBe(0);
    expect(mgr.getSteeringCount()).toBe(0);
  });

  test("preserves chronological order: injected first, then buffered", () => {
    mgr.addSteering("first", 50);
    mgr.trackBufferedMessagesForInjection();
    mgr.consumeSteering();
    mgr.addSteering("second", 51);

    const extracted = mgr.extractSteeringMessages();
    expect(extracted[0].content).toBe("first");
    expect(extracted[1].content).toBe("second");
  });
});

describe("SteeringManager.hasSteeringMessages", () => {
  test("returns true when only injectedSteeringDuringQuery has messages", () => {
    const mgr = makeManager();
    mgr.addSteering("injected", 60, "Bash");
    mgr.trackBufferedMessagesForInjection();
    mgr.consumeSteering(); // buffer empty, injected has 1

    // Before fix: would return false (only checked steeringBuffer)
    expect(mgr.hasSteeringMessages()).toBe(true);
  });

  test("returns false when both stores are empty", () => {
    const mgr = makeManager();
    expect(mgr.hasSteeringMessages()).toBe(false);
  });

  test("returns true when only steeringBuffer has messages", () => {
    const mgr = makeManager();
    mgr.addSteering("buffered", 61);
    expect(mgr.hasSteeringMessages()).toBe(true);
  });
});

describe("SteeringManager.reset", () => {
  test("clears all state", () => {
    const mgr = makeManager();
    mgr.addSteering("x", 1);
    mgr.trackBufferedMessagesForInjection();
    mgr.addSteering("y", 2);
    mgr.setPendingRecovery([], 999);

    mgr.reset();

    expect(mgr.extractSteeringMessages()).toEqual([]);
    expect(mgr.getInjectedCount()).toBe(0);
    expect(mgr.getSteeringCount()).toBe(0);
    expect(mgr.hasPendingRecovery()).toBe(false);
    expect(mgr.evictionCount).toBe(0);
  });
});

